UPDATE push_task
SET status = 'FAILED',
    status_message = #{statusMessage},
    send_completed_at = #{failedAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id = #{id}

UPDATE push_task
SET cleared_at = #{clearedAt, typeHandler=com.pk.infra.mybatis.typehandler.InstantTypeHandler}
WHERE id IN

    #{taskId}

  AND cleared_at IS NULL
